// U34 probe (not committed): parses the notepad's reconciliation table and
// compares each row's class and anchor with the catalogue measured by the
// U29 pin's resolution logic (scripts/__tests__/gm-two-player-acceptance-gates.test.ts).
// Usage: node probe.cjs <repoRoot> [notepadPath]
const fs = require('node:fs');
const path = require('node:path');
const repoRoot = path.resolve(process.argv[2] || '.');
const notepad = process.argv[3] || path.join(repoRoot, 'openspec/changes/adopt-combat-journal-cutover-and-gm-rewind/notepad.md');
const read = (f) => fs.readFileSync(path.join(repoRoot, f), 'utf8');
const lineOf = (t, o) => t.slice(0, o).split('\n').length;
const core = require(path.join(repoRoot, 'scripts/qc/gm-two-player-campaign-core.cjs'));
const gates = require(path.join(repoRoot, 'scripts/qc/gm-two-player-acceptance-gates.cjs'));
// --- measured catalogue (pin logic: catalogue headings, all-plan specs, titleIds, manifest)
const runSpecs = core.buildRunPlan({ group: 'all', runId: 'u34-probe', repoRoot }).args.filter((a) => a.startsWith('e2e/'));
const catalogue = [...read('openspec/changes/harden-gm-two-player-campaign-sessions/specs/e2e-testing/spec.md').matchAll(/^#### Scenario: (E2E-\d{2}) /gm)].map((m) => m[1]);
const titles = [];
const marks = [];
for (const file of runSpecs) {
  const text = read(file);
  for (const m of text.matchAll(/\btest\(\s*(['"`])((?:(?!\1)[\s\S])*)\1/g)) {
    const ids = [...m[2].matchAll(/@(E2E-\d{2})\b/g)].map((t) => t[1]);
    if (ids.length) titles.push({ file, line: lineOf(text, m.index), offset: m.index, ids });
  }
  for (const m of text.matchAll(/\btest(?:\.describe)?(?:\.(?:serial|parallel))?\.fail\s*\(/g)) {
    const call = text.slice(m.index, text.indexOf(');', m.index) + 2);
    const tag = Object.keys(gates.NAMED_GATES).find((t) => call.includes(t));
    const owner = titles.filter((t) => t.file === file && t.offset < m.index).pop();
    if (tag && owner) marks.push({ file, line: lineOf(text, m.index), tag, owner });
  }
}
const manifestText = read('scripts/qc/gm-two-player-acceptance-gates.cjs');
const measured = new Map(catalogue.map((id) => {
  const own = titles.filter((t) => t.ids.includes(id));
  const gated = gates.GATED_ABSENT.find((e) => e.id === id);
  if (own.length) {
    const fail = marks.find((mk) => own.includes(mk.owner));
    return [id, { cls: fail ? 'strict-expected-failure' : 'real', anchors: own.map((t) => `${t.file}:${t.line}`), mark: fail && `${fail.file}:${fail.line}`, gate: fail && fail.tag }];
  }
  if (id === gates.EXACT_MAIN_CONTRACT.id) return [id, { cls: 'real', contract: gates.EXACT_MAIN_CONTRACT.path }];
  if (gated) return [id, { cls: 'manifest-gated', gate: gated.gateTag, holder: gated.holder, anchors: [`scripts/qc/gm-two-player-acceptance-gates.cjs:${lineOf(manifestText, manifestText.indexOf(`'${id}'`))}`] }];
  return [id, { cls: 'absent' }];
}));
// --- the notepad's table
const rows = fs.readFileSync(notepad, 'utf8').split(/\r?\n/).filter((l) => /^\|\s*E2E-\d{2}\b/.test(l)).map((l) => {
  const cells = l.split('|').slice(1, -1).map((c) => c.trim());
  return { id: cells[0].match(/E2E-\d{2}/)[0], cls: cells[1], anchor: cells[2] || '', successor: cells[4] || '' };
});
const out = [];
const seen = new Map();
for (const r of rows) seen.set(r.id, (seen.get(r.id) || 0) + 1);
for (const id of catalogue) if (!seen.has(id)) out.push(`${id}: missing from the table`);
for (const [id, n] of seen) if (n > 1) out.push(`${id}: ${n} rows`);
for (const r of rows) {
  const m = measured.get(r.id);
  if (!m) { out.push(`${r.id}: not a catalogue id`); continue; }
  const clsToken = r.cls.replace(/`/g, '').split(/\s+/)[0];
  if (clsToken !== m.cls) { out.push(`${r.id}: class "${r.cls}" but measured ${m.cls}${m.gate ? ' ' + m.gate : ''}`); continue; }
  const cited = [...r.anchor.matchAll(/((?:e2e|scripts)\/[\w./-]+?):(\d+)/g)].map((x) => `${x[1]}:${x[2]}`);
  const problems = [];
  for (const a of cited) { const f = a.replace(/:\d+$/, ''); if (f.startsWith('e2e/') && !runSpecs.includes(f)) problems.push(`${f} is not run by the all plan`); }
  if (m.contract) { if (!r.anchor.includes(m.contract)) problems.push(`anchor lacks the contract ${m.contract}`); }
  else {
    const want = [...m.anchors, ...(m.mark ? [m.mark] : [])].sort();
    const got = [...new Set(cited)].sort();
    if (JSON.stringify(want) !== JSON.stringify(got)) problems.push(`anchor [${got.join(', ')}] but measured [${want.join(', ')}]`);
  }
  if (m.gate && !r.cls.includes(m.gate)) problems.push(`class names no gate ${m.gate}`);
  if (m.holder && !r.successor.includes(m.holder.split(' ')[0])) problems.push(`successor lacks holder ${m.holder}`);
  if (problems.length) out.push(`${r.id}: ${problems.join('; ')}`);
}
for (const line of out) console.log(`DISAGREE ${line}`);
console.log(`rows=${rows.length} catalogue=${catalogue.length} disagreements=${out.length}`);
process.exitCode = out.length ? 1 : 0;
